fn product(a: &Vec<u32>, b: &Vec<u32>) -> Vec<u32> {
    // Ensure both vectors have the same length (as per problem statement)
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    
    // Use iterators to pair elements, multiply, and collect into a new Vec
    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| x * y)
        .collect()
}